        "display_only_dimensions": list(DISPLAY_ONLY_DIMENSIONS),
        "overall_score": None,
        "dimensions": [asdict(item) for item in REGISTRY],
    }
    encoded = json.dumps(body, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
    body["registry_sha256"] = hashlib.sha256(encoded).hexdigest()
    return body
from __future__ import annotations

import hashlib
import json
import math
import sqlite3
from pathlib import Path
from typing import Any, Iterable

from .quality import evaluate_quality
from .registry import REGISTRY, registry_document
from .scoring import transform_value


SCHEMA = """
CREATE TABLE IF NOT EXISTS samples (
  sample_id TEXT PRIMARY KEY,
  content_sha256 TEXT,
  perceptual_hash TEXT,
  quality_status TEXT NOT NULL,
  reason_codes_json TEXT NOT NULL,
  algorithm_version TEXT,
  metrics_schema_version TEXT,
  source_path TEXT,
  source_line INTEGER
);
CREATE TABLE IF NOT EXISTS evidence (
  sample_id TEXT NOT NULL,
  metric_id TEXT NOT NULL,
  raw_value REAL NOT NULL,
  transformed_value REAL NOT NULL,
  PRIMARY KEY(sample_id, metric_id)
);
CREATE INDEX IF NOT EXISTS evidence_metric_value
  ON evidence(metric_id, transformed_value);
CREATE TABLE IF NOT EXISTS imports (
  source_path TEXT PRIMARY KEY,
  size_bytes INTEGER NOT NULL,
  mtime_ns INTEGER NOT NULL,
  last_line INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS perceptual_hash_bands (
  sample_id TEXT NOT NULL,
  band INTEGER NOT NULL,
  band_value TEXT NOT NULL,
  PRIMARY KEY(sample_id, band)
);
CREATE INDEX IF NOT EXISTS perceptual_band_lookup
  ON perceptual_hash_bands(band, band_value);
"""


def _path(document: dict[str, Any], dotted: str) -> Any:
    current: Any = document
    for part in dotted.split("."):
        if not isinstance(current, dict):
            return None
        current = current.get(part)
    return current


def _sample_id(observation: dict[str, Any]) -> str:
    signature = observation.get("signature") or {}
    content_hash = observation.get("content_sha256") or signature.get("sha256")
    if content_hash:
        return str(content_hash)
    canonical = json.dumps(
        {"relative_path": signature.get("relative_path"), "size": signature.get("size"), "mtime_ns": signature.get("mtime_ns")},
        ensure_ascii=False, sort_keys=True, separators=(",", ":"),
    )
    return hashlib.sha256(canonical.encode()).hexdigest()


def initialize_database(path: Path) -> sqlite3.Connection:
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path)
    connection.execute("PRAGMA journal_mode=WAL")
    connection.execute("PRAGMA synchronous=NORMAL")
    connection.executescript(SCHEMA)
    return connection


def _perceptual_duplicate(connection: sqlite3.Connection, perceptual_hash: str | None) -> str | None:
    if not perceptual_hash or len(perceptual_hash) != 16:
        return None
    candidates: set[str] = set()
    for band in range(4):
        value = perceptual_hash[band * 4:(band + 1) * 4]
        candidates.update(row[0] for row in connection.execute(
            "SELECT sample_id FROM perceptual_hash_bands WHERE band=? AND band_value=?", (band, value)
        ))
    target = int(perceptual_hash, 16)
    for sample_id in candidates:
        row = connection.execute("SELECT perceptual_hash FROM samples WHERE sample_id=?", (sample_id,)).fetchone()
        if row and row[0] and (target ^ int(row[0], 16)).bit_count() <= 4:
            return sample_id
    return None


def _insert_perceptual_bands(connection: sqlite3.Connection, sample_id: str, perceptual_hash: str | None) -> None:
    if not perceptual_hash or len(perceptual_hash) != 16:
        return
    connection.executemany(
        "INSERT OR IGNORE INTO perceptual_hash_bands VALUES (?,?,?)",
        [(sample_id, band, perceptual_hash[band * 4:(band + 1) * 4]) for band in range(4)],
    )


def ingest_jsonl(
    jsonl_paths: Iterable[Path],
    database: Path,
    *,
    workspace_limit_bytes: int = 10 * 1024 ** 3,
) -> dict[str, int]:
    """流式、可断点、只追加地收集评分证据，不修改任何原始文件。"""
    connection = initialize_database(database)
    counters = {"seen": 0, "inserted": 0, "duplicate": 0, "excluded": 0, "invalid": 0}
    try:
        for source in sorted(Path(item).resolve() for item in jsonl_paths):
            stat = source.stat()
            last_line = 0
            previous = connection.execute(
                "SELECT size_bytes,mtime_ns,last_line FROM imports WHERE source_path=?", (str(source),)
            ).fetchone()
            start_line = int(previous[2]) if previous and previous[:2] == (stat.st_size, stat.st_mtime_ns) else 0
            with source.open("r", encoding="utf-8") as handle:
                for line_number, line in enumerate(handle, 1):
                    last_line = line_number
                    if line_number <= start_line or not line.strip():
                        continue
                    counters["seen"] += 1
                    try:
                        observation = json.loads(line)
                        features = observation.get("features") or observation.get("scoring_features")
                        if not isinstance(features, dict):
                            raise ValueError("missing features")
                    except (json.JSONDecodeError, ValueError):
                        counters["invalid"] += 1
                        continue
                    gate = evaluate_quality(observation)
                    sample_id = _sample_id(observation)
                    if connection.execute("SELECT 1 FROM samples WHERE sample_id=?", (sample_id,)).fetchone():
                        counters["duplicate"] += 1
                        continue
                    perceptual_hash = observation.get("perceptual_hash")
                    if _perceptual_duplicate(connection, perceptual_hash):
                        counters["duplicate"] += 1
                        continue
                    connection.execute(
                        "INSERT INTO samples VALUES (?,?,?,?,?,?,?,?,?)",
                        (
                            sample_id, observation.get("content_sha256"), perceptual_hash,
                            gate["status"], json.dumps(gate["reason_codes"], ensure_ascii=False),
                            observation.get("algorithm_version"), observation.get("metrics_schema_version"),
                            str(source), line_number,
                        ),
                    )
                    _insert_perceptual_bands(connection, sample_id, perceptual_hash)
                    if gate["status"] != "PASS":
                        counters["excluded"] += 1
                    else:
                        rows = []
                        for dimension in REGISTRY:
                            for group in dimension.groups:
                                for metric in group.metrics:
                                    value = _path(features, metric.source)
                                    if isinstance(value, bool) or not isinstance(value, (int, float)):
                                        continue
                                    value = float(value)
                                    if not math.isfinite(value):
                                        continue
                                    rows.append((sample_id, metric.id, value, transform_value(value, metric.transform)))
                        connection.executemany("INSERT INTO evidence VALUES (?,?,?,?)", rows)
                    counters["inserted"] += 1
                    if counters["seen"] % 500 == 0:
                        connection.commit()
                        if database.stat().st_size > workspace_limit_bytes:
                            raise RuntimeError("评分工作库超过10GiB限制，已安全停止且保留断点")
            connection.execute(
                "INSERT OR REPLACE INTO imports VALUES (?,?,?,?)",
                (str(source), stat.st_size, stat.st_mtime_ns, last_line),
            )
            connection.commit()
    finally:
        connection.close()
    return counters


def build_exact_profile(database: Path) -> dict[str, Any]:
    connection = sqlite3.connect(database)
    try:
        references: dict[str, list[float]] = {}
        effective_counts: dict[str, int] = {}
        for dimension in REGISTRY:
            for group in dimension.groups:
                for metric in group.metrics:
                    values = [float(row[0]) for row in connection.execute(
                        "SELECT transformed_value FROM evidence WHERE metric_id=? ORDER BY transformed_value", (metric.id,)
                    )]
                    references[metric.id] = values
                    effective_counts[metric.id] = len(values)
        sample_counts = dict(connection.execute(
            "SELECT quality_status,COUNT(*) FROM samples GROUP BY quality_status"
        ).fetchall())
    finally:
        connection.close()
    return {
        **registry_document(),
        "reference_storage": "full_empirical_cdf_sorted_values",
        "reference_sample_counts": sample_counts,
        "effective_metric_counts": effective_counts,
        "references": references,
    }
from __future__ import annotations

import bisect
import hashlib
import json
import math
from typing import Any

from .quality import evaluate_quality
from .registry import DISPLAY_ONLY_DIMENSIONS, REGISTRY, MetricSpec, registry_document


def transform_value(value: float, transform: str) -> float:
    if not math.isfinite(value):
        raise ValueError("指标值不是有限数")
    if transform == "identity":
        return value
    if transform == "log1p":
        if value < 0:
            raise ValueError("log1p指标不得为负数")
        return math.log1p(value)
    raise ValueError(f"未知变换: {transform}")


def empirical_percentile(value: float, reference: list[float], direction: str = "high") -> tuple[float, dict[str, Any]]:
    """完整经验CDF；并列值使用中位秩，不截断到0.5/99.5。"""
    if not reference:
        raise ValueError("参考分布为空")
    values = sorted(float(item) for item in reference if math.isfinite(float(item)))
    if not values:
        raise ValueError("参考分布没有有限值")
    left = bisect.bisect_left(values, value)
    right = bisect.bisect_right(values, value)
    midrank = (left + right) / 2.0
    percentile = 100.0 * midrank / len(values)
    if direction == "low":
        percentile = 100.0 - percentile
    return percentile, {
        "reference_count": len(values),
        "cdf_left_count": left,
        "cdf_right_count": right,
        "tie_count": right - left,
        "midrank": midrank,
    }


def _metric_score(metric: MetricSpec, raw_value: float, references: dict[str, list[float]]) -> tuple[float, dict[str, Any]]:
    transformed = transform_value(float(raw_value), metric.transform)
    reference = list(references.get(metric.id) or [])
    if metric.zero_is_no_burden and float(raw_value) == 0:
        return 0.0, {
            "raw_value": float(raw_value), "transformed_value": transformed,
            "score": 0.0, "mapping": "zero_burden", "reference_count": len(reference),
        }
    if metric.zero_inflated:
        reference = [item for item in reference if item > 0]
        mapping = "positive_only_empirical_cdf"
    else:
        mapping = "full_empirical_cdf"
    score, detail = empirical_percentile(transformed, reference, metric.direction)
    return score, {
        "raw_value": float(raw_value), "transformed_value": transformed,
        "score": score, "mapping": mapping, "direction": metric.direction,
        "transform": metric.transform, "unit": metric.unit, **detail,
    }


def _get_path(features: dict[str, Any], path: str) -> Any:
    node: Any = features
    for part in path.split("."):
        if not isinstance(node, dict) or part not in node:
            return None
        node = node[part]
    return node


def score_observation(
    observation: dict[str, Any],
    references: dict[str, list[float]],
    *,
    include_legacy_shadow: bool = False,
    normalization_profile_sha256: str | None = None,
    scoring_profile_version: str | None = None,
) -> dict[str, Any]:
    config = registry_document()
    gate = evaluate_quality(observation)
    features = observation.get("features") or observation.get("scoring_features") or {}
    dimensions: list[dict[str, Any]] = []
    formal_allowed = gate["status"] == "PASS"

    for dimension in REGISTRY:
        groups: list[dict[str, Any]] = []
        missing_groups: list[str] = []
        for group in dimension.groups:
            metric_rows: list[dict[str, Any]] = []
            missing_metrics: list[str] = []
            for metric in group.metrics:
                raw = _get_path(features, metric.source)
                count = _get_path(features, metric.source.split(".")[0] + ".instance_count")
                if metric.minimum_instances and count is not None and int(count) < metric.minimum_instances:
                    missing_metrics.append(metric.id)
                    continue
                if raw is None or isinstance(raw, bool) or not isinstance(raw, (int, float)):
                    missing_metrics.append(metric.id)
                    continue
                try:
                    score, detail = _metric_score(metric, float(raw), references)
                except ValueError:
                    missing_metrics.append(metric.id)
                    continue
                metric_rows.append({
                    "metric_id": metric.id, "canonical_source": metric.source,
                    "metric_weight": metric.weight, **detail,
                })
            if missing_metrics:
                missing_groups.append(group.id)
                groups.append({
                    "group_id": group.id, "group_name": group.name, "group_weight": group.weight,
                    "status": "insufficient_evidence", "missing_metrics": missing_metrics,
                    "metrics": metric_rows, "score": None,
                })
                continue
            group_score = sum(row["score"] * row["metric_weight"] for row in metric_rows)
            groups.append({
                "group_id": group.id, "group_name": group.name, "group_weight": group.weight,
                "status": "scored", "missing_metrics": [], "metrics": metric_rows,
                "score": group_score,
            })
        if not formal_allowed:
            status = "shadow_only" if gate["status"] == "REVIEW" else "not_scored"
            dimension_score = None
        elif missing_groups:
            status = "insufficient_evidence"
            dimension_score = None
        else:
            status = "formal"
            dimension_score = sum(row["score"] * row["group_weight"] for row in groups)
        dimensions.append({
            "dimension_id": dimension.id, "dimension_name": dimension.name,
            "status": status, "score": dimension_score, "groups": groups,
            "missing_required_groups": missing_groups,
        })

    result: dict[str, Any] = {
        "scoring_profile_version": scoring_profile_version or config["scoring_profile_version"],
        "calibration_status": config["status"],
        "score_direction": config["score_direction"],
        "quality_gate": gate,
        "formal_dimension_scores": dimensions,
        "display_only_dimensions": list(DISPLAY_ONLY_DIMENSIONS),
        "overall_score": None,
        "overall_grade": None,
        "registry_sha256": config["registry_sha256"],
        "normalization_profile_sha256": normalization_profile_sha256,
    }
    if include_legacy_shadow:
        result["legacy_shadow_score"] = observation.get("legacy_score")
    stable = json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    result["trace_sha256"] = hashlib.sha256(stable.encode()).hexdigest()
    return result

