from __future__ import annotations

import copy
import hashlib
import json
import math
import sqlite3
from pathlib import Path
from typing import Any

from src.scoring_calibration.v011.scoring import transform_value


SHADOW_PROFILE_VERSION = "aisia_scoring_v0.1.2_front5_shadow_20260807"
UV_SOURCES = {
    "uv_spot_density": ("UV样色素范围", "density", "log1p"),
    "uv_spot_area_ratio": ("UV样色素范围", "area_ratio", "identity"),
    "uv_p90_intensity": ("UV样色素强度", "p90_intensity", "identity"),
    "uv_high_intensity_area_ratio": ("UV样色素强度", "high_intensity_ratio", "identity"),
}


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def build_uv_shadow_profile(
    official_profile_path: str | Path,
    sqlite_path: str | Path,
    output_path: str | Path,
) -> dict[str, Any]:
    """Create a new shadow profile without mutating the V0.1.1 profile.

    Only the three missing UV reference arrays are appended. The PASS set and
    all existing reference arrays are inherited byte-for-byte in value from
    the official profile and the existing V0.1.1 SQLite gate database.
    """
    official_path = Path(official_profile_path).resolve()
    db_path = Path(sqlite_path).resolve()
    target = Path(output_path).resolve()
    official = json.loads(official_path.read_text(encoding="utf-8"))
    if official.get("scoring_profile_version") != "aisia_scoring_v0.1.1_integrity_full_reference_20260807":
        raise ValueError("只允许从V0.1.1全量历史正式配置派生shadow")

    connection = sqlite3.connect(db_path)
    try:
        pass_rows = connection.execute(
            "SELECT relative_path, source_jsonl FROM samples WHERE gate_status='PASS'"
        ).fetchall()
    finally:
        connection.close()
    allowed_by_source: dict[str, set[str]] = {}
    for relative_path, source in pass_rows:
        allowed_by_source.setdefault(str(source), set()).add(str(relative_path))

    raw_values = {metric_id: [] for metric_id in UV_SOURCES}
    for source, allowed in sorted(allowed_by_source.items()):
        with Path(source).open("r", encoding="utf-8") as handle:
            for line in handle:
                record = json.loads(line)
                relative_path = str((record.get("signature") or {}).get("relative_path") or "")
                if relative_path not in allowed:
                    continue
                uv = (record.get("scoring_features") or {}).get("uv_spots") or {}
                for metric_id, (group, key, _transform) in UV_SOURCES.items():
                    value = (uv.get(group) or {}).get(key)
                    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
                        raise ValueError(f"PASS历史记录缺少UV字段: {relative_path} {metric_id}")
                    raw_values[metric_id].append(float(value))

    expected = len(pass_rows)
    if any(len(values) != expected for values in raw_values.values()):
        raise ValueError("UV参考数组长度与PASS样本数不一致")

    shadow = copy.deepcopy(official)
    shadow["scoring_profile_version"] = SHADOW_PROFILE_VERSION
    shadow["profile_role"] = "shadow"
    shadow["promotion_status"] = "not_promoted"
    shadow["official_profile_version"] = official["scoring_profile_version"]
    shadow["official_profile_sha256"] = _sha256(official_path)
    shadow["uv_weight_source"] = "engineering_default_equal_v1"
    shadow["uv_internal_metric_weights"] = {metric_id: .25 for metric_id in UV_SOURCES}
    shadow["uv_source_trace"] = {
        "source_algorithm": "purple_analysis.uv_spots",
        "source_version": "current_historical_generation",
        "input_modality": "white_light_rgb",
        "product_modality": "UV",
        "uv_generation_version": "historical_uv_generation_v1",
    }
    for metric_id, (_group, _key, transform) in UV_SOURCES.items():
        shadow.setdefault("references", {})[metric_id] = sorted(
            transform_value(value, transform) for value in raw_values[metric_id]
        )
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(shadow, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")
    return {
        "path": str(target),
        "sha256": _sha256(target),
        "official_profile_unchanged_sha256": _sha256(official_path),
        "sample_count": expected,
        "metric_counts": {key: len(value) for key, value in raw_values.items()},
    }
from __future__ import annotations

import hashlib
import json
from typing import Any

from src.scoring_calibration.v011.registry import REGISTRY
from src.scoring_calibration.v011.scoring import empirical_percentile, transform_value

from .explanation import build_score_explanation


UV_METRICS = (
    ("uv_spot_density", "uv_spots.UV样色素范围.density", "log1p", "个/10万有效皮肤像素"),
    ("uv_spot_area_ratio", "uv_spots.UV样色素范围.area_ratio", "identity", "比例"),
    ("uv_p90_intensity", "uv_spots.UV样色素强度.p90_intensity", "identity", "0-1"),
    ("uv_high_intensity_area_ratio", "uv_spots.UV样色素强度.high_intensity_ratio", "identity", "比例"),
)


def _get_path(document: dict[str, Any], path: str) -> Any:
    node: Any = document
    for part in path.split("."):
        if not isinstance(node, dict) or part not in node:
            return None
        node = node[part]
    return node


def _score_metric(metric_id: str, raw: float, transform: str, references: dict[str, list[float]], unit: str) -> dict[str, Any]:
    transformed = transform_value(float(raw), transform)
    reference = list(references.get(metric_id) or [])
    if raw == 0:
        score = 0.0
        detail = {"reference_count": len(reference), "mapping": "zero_burden"}
    else:
        if metric_id in {"uv_spot_density", "uv_spot_area_ratio"}:
            reference = [value for value in reference if value > 0]
        score, detail = empirical_percentile(transformed, reference)
    return {
        "metric_id": metric_id,
        "raw_value": float(raw),
        "transformed_value": transformed,
        "score": score,
        "unit": unit,
        "transform": transform,
        "metric_weight": .25,
        **detail,
    }


def _v011_pigment_dimension(features: dict[str, Any], references: dict[str, list[float]]) -> dict[str, Any]:
    dimension = next(item for item in REGISTRY if item.id == "combined_pigmentation")
    groups: list[dict[str, Any]] = []
    for group in dimension.groups:
        if group.id == "uv_spots":
            metrics = []
            for metric_id, source, transform, unit in UV_METRICS:
                raw = _get_path(features, source)
                if not isinstance(raw, (int, float)):
                    raise ValueError(f"综合色素shadow缺少UV指标: {metric_id}")
                metrics.append(_score_metric(metric_id, float(raw), transform, references, unit))
            group_score = sum(row["score"] * row["metric_weight"] for row in metrics)
            groups.append({
                "group_id": group.id,
                "group_name": "UV下更明显的色斑负担",
                "group_weight": group.weight,
                "score": group_score,
                "status": "scored",
                "metrics": metrics,
                "weight_source": "engineering_default_equal_v1",
            })
            continue
        metric_rows = []
        for metric in group.metrics:
            raw = _get_path(features, metric.source)
            if not isinstance(raw, (int, float)):
                raise ValueError(f"综合色素shadow缺少指标: {metric.id}")
            transformed = transform_value(float(raw), metric.transform)
            reference = list(references.get(metric.id) or [])
            if metric.zero_is_no_burden and float(raw) == 0:
                score = 0.0
                detail = {"reference_count": len(reference), "mapping": "zero_burden"}
            else:
                if metric.zero_inflated:
                    reference = [value for value in reference if value > 0]
                score, detail = empirical_percentile(transformed, reference, metric.direction)
            metric_rows.append({
                "metric_id": metric.id,
                "raw_value": float(raw),
                "transformed_value": transformed,
                "score": score,
                "unit": metric.unit,
                "transform": metric.transform,
                "metric_weight": metric.weight,
                **detail,
            })
        groups.append({
            "group_id": group.id,
            "group_name": group.name,
            "group_weight": group.weight,
            "score": sum(row["score"] * row["metric_weight"] for row in metric_rows),
            "status": "scored",
            "metrics": metric_rows,
        })
    score = sum(row["score"] * row["group_weight"] for row in groups)
    return {
        "dimension_id": "combined_pigmentation",
        "dimension_name": "综合色素问题",
        "status": "shadow",
        "score_status": "shadow_v012",
        "score": score,
        "groups": groups,
        "reference_scope": "full_history_global_ecdf",
        "formal_formula": "Visible 40% + UV 25% + Brown 35%",
        "red_weight": 0.0,
    }


def score_combined_pigmentation_shadow(features: dict[str, Any], profile: dict[str, Any]) -> dict[str, Any]:
    row = _v011_pigment_dimension(features, profile.get("references") or {})
    row["score_explanation"] = build_score_explanation(row)
    stable = json.dumps(row, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    row["trace_sha256"] = hashlib.sha256(stable.encode()).hexdigest()
    return row
from __future__ import annotations

import copy
from typing import Any


PORE_GROUP_NAMES = {
    "density": "毛孔密度（当前V0.1.1评分口径）",
    "coverage": "毛孔面积覆盖（当前V0.1.1评分口径）",
    "size": "典型毛孔面积P50（当前V0.1.1评分口径）",
    "large_pores": "偏大毛孔面积P90代理（当前V0.1.1评分口径）",
    "shape": "毛孔形态不规则度（当前V0.1.1评分口径）",
}


def _evidence_summary(group: dict[str, Any]) -> str:
    rows: list[str] = []
    for metric in group.get("metrics", []):
        raw = metric.get("raw_value")
        unit = metric.get("unit") or ""
        rows.append(f"{metric.get('metric_id')}={raw}{unit}")
    return "；".join(rows)


def _contrastive_text(dimension_id: str, drivers: list[dict[str, Any]]) -> str:
    if not drivers:
        return "当前没有足够的评分组用于解释。"
    high = drivers[0]
    low = drivers[-1]
    if dimension_id == "diffuse_redness":
        return (
            f"最终分同时考虑覆盖、强度、连续性和边界均匀性；"
            f"其中{high['name']}贡献最高，{low['name']}贡献相对最低，"
            "因此不能仅根据红区面积判断最终程度。"
        )
    if dimension_id == "combined_pigmentation":
        return (
            f"综合色素由Visible、UV和Brown三类信号共同形成；"
            f"本次主要由{high['name']}驱动，{low['name']}负担相对较轻。"
        )
    if dimension_id == "visible_pores":
        return (
            f"当前V0.1.1毛孔分主要由{high['name']}驱动；"
            "P90面积仅为偏大毛孔代理，不等同于医生目标口径中的大毛孔比例或大毛孔面积占比。"
        )
    return f"本次主要由{high['name']}驱动，{low['name']}贡献相对最低。"


def build_score_explanation(dimension: dict[str, Any]) -> dict[str, Any] | None:
    score = dimension.get("score")
    if not isinstance(score, (int, float)):
        return None
    dimension_id = str(dimension.get("dimension_id") or "")
    drivers: list[dict[str, Any]] = []
    for group in dimension.get("groups", []):
        group_score = group.get("score")
        weight = group.get("group_weight")
        if not isinstance(group_score, (int, float)) or not isinstance(weight, (int, float)):
            continue
        name = str(group.get("group_name") or group.get("group_id") or "")
        if dimension_id == "visible_pores":
            name = PORE_GROUP_NAMES.get(str(group.get("group_id")), name)
        drivers.append({
            "id": group.get("group_id"),
            "name": name,
            "score": float(group_score),
            "weight": float(weight),
            "weighted_contribution": float(group_score) * float(weight),
            "evidence_summary": _evidence_summary(group),
        })
    drivers.sort(key=lambda row: row["weighted_contribution"], reverse=True)
    contribution = sum(row["weighted_contribution"] for row in drivers)
    if abs(contribution - float(score)) > 1e-6:
        raise ValueError(
            f"评分组贡献与维度分不一致: {dimension_id} {contribution} != {score}"
        )
    return {
        "dominant_driver": drivers[0] if drivers else None,
        "secondary_driver": drivers[1] if len(drivers) > 1 else None,
        "lowest_driver": drivers[-1] if drivers else None,
        "drivers": drivers,
        "contrastive_explanation": _contrastive_text(dimension_id, drivers),
        "summary_text": (
            f"综合问题负担分为{float(score):.2f}分。"
            + _contrastive_text(dimension_id, drivers)
        ),
    }


def attach_score_explanations(scoring: dict[str, Any]) -> dict[str, Any]:
    output = copy.deepcopy(scoring)
