from __future__ import annotations

import copy

import pytest

from src.scoring_calibration.v012.explanation import attach_score_explanations
from src.scoring_calibration.v012.pigmentation import score_combined_pigmentation_shadow


def _references() -> dict[str, list[float]]:
    ids = {
        "visible_spot_density", "visible_spot_area_ratio", "visible_spot_p90_delta_e",
        "visible_spot_patch_ratio", "uv_spot_density", "uv_spot_area_ratio",
        "uv_p90_intensity", "uv_high_intensity_target_ratio", "brown_area_ratio",
        "brown_p90_intensity", "brown_high_intensity_ratio", "brown_patch_ratio",
    }
    return {metric_id: [0.1, 0.2, 0.3, 0.4] for metric_id in ids}


def _features() -> dict:
    return {
        "spots": {
            "可见色斑范围": {"density": 0.3, "area_ratio": 0.3},
            "可见色斑对比": {"p90_delta_e": 0.3},
            "可见色斑形态": {"patch_area_ratio": 0.3},
        },
        "uv_spots": {
            "UV样色素范围": {"density": 0.3, "area_ratio": 0.3},
            "UV样色素强度": {"p90_intensity": 0.3, "high_intensity_ratio": 0.3},
        },
        "brown": {
            "Brown覆盖负担": {"area_ratio": 0.3},
            "Brown强度": {"p90_intensity": 0.3},
            "高强度Brown区域": {"high_intensity_area_ratio": 0.3},
            "Brown点片形态": {"patch_area_ratio": 0.3},
        },
    }


def test_uv_equal_weights_are_engineering_default_and_red_is_zero() -> None:
    profile = {"references": _references()}
    result = score_combined_pigmentation_shadow(_features(), profile)
    assert result["score_status"] == "shadow_v012"
    assert result["red_weight"] == 0
    uv_group = next(group for group in result["groups"] if group["group_id"] == "uv_spots")
    assert uv_group["weight_source"] == "engineering_default_equal_v1"
    assert [metric["metric_weight"] for metric in uv_group["metrics"]] == [.25] * 4
    contributions = result["score_explanation"]["drivers"]
    assert sum(item["weighted_contribution"] for item in contributions) == pytest.approx(result["score"])


def test_red_auxiliary_change_cannot_change_shadow_score() -> None:
    profile = {"references": _references()}
    features = _features()
    first = score_combined_pigmentation_shadow(features, profile)
    changed = copy.deepcopy(features)
    changed["red_auxiliary"] = {"red_brown_mixed": 999, "pure_red_suspected": 888}
    second = score_combined_pigmentation_shadow(changed, profile)
    assert second["score"] == first["score"]
    assert second["groups"] == first["groups"]


def test_pore_explanation_uses_proxy_wording() -> None:
    scoring = {
        "formal_dimension_scores": [{
            "dimension_id": "visible_pores",
            "score": 50.0,
            "groups": [
                {"group_id": "density", "group_name": "x", "group_weight": .2, "score": 50.0, "metrics": []},
